package cn.richie696.component.secret.provider.pkcs11;
import cn.richie696.component.secret.api.exception.SecretConfigurationException; import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.util.TreeMap;
final class Pkcs11SecretConfiguration { private Pkcs11SecretConfiguration(){} static void validate(Pkcs11SecretProperties p){if(p.getLibrary()==null||p.getLibrary().isBlank())throw new SecretConfigurationException("SEC-BOOT-003","PKCS#11 library is required");if(p.getPin().length==0)throw new SecretConfigurationException("SEC-BOOT-003","PKCS#11 PIN is required");if(p.getKeyBindings().isEmpty())throw new SecretConfigurationException("SEC-BOOT-003","PKCS#11 key-bindings are required");for(var e:p.getKeyBindings().entrySet()){safe(e.getKey(),"PKCS#11 logical key");safe(e.getValue(),"PKCS#11 key alias");}} static String hash(String id,Pkcs11SecretProperties p){String c=id+"\n"+p.getLibrary()+"\n"+p.getSlot()+"\n"+p.getTokenLabel()+"\n"+p.getSigningAlgorithm()+"\n"+new TreeMap<>(p.getKeyBindings());try{return java.util.HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(c.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}} private static void safe(String v,String l){if(v==null||v.isBlank()||v.contains("..")||v.contains("/"))throw new SecretConfigurationException("SEC-BOOT-003",l+" is invalid");} }
